<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,ref} from 'vue';
import AppDialog from './AppDialog.vue';

type Role='administrador'|'operador'|'cliente';
type Member={id:number;nome:string;email:string;papel?:'administrador'|'operador';cliente_id?:number;ativo:boolean};
type UserResponse={funcionarios?:Member[];representantes?:Member[]}|Member[];
type Client={id:number;razao_social:string;ativo?:boolean};
const props=defineProps<{request:<T>(path:string,method?:string,body?:unknown,signal?:AbortSignal)=>Promise<T>}>();
const members=ref<Member[]>([]),clients=ref<Client[]>([]),loading=ref(false),loaded=ref(false),error=ref(''),notice=ref(''),editing=ref(false),saving=ref(false),formError=ref(''),actionError=ref('');
const mode=ref<'cadastrar'|'vincular'>('vincular'),name=ref(''),email=ref(''),password=ref(''),role=ref<Role>('operador'),clientId=ref('');
let alive=true,generation=0;
const activeMembers=computed(()=>members.value.filter(item=>item.ativo).length);
function normalize(value:UserResponse):Member[]{return Array.isArray(value)?value:[...(value.funcionarios||[]),...(value.representantes||[])];}
function message(cause:unknown){return (cause as Error)?.message||'Não foi possível concluir a operação.';}
async function load(){if(loading.value)return;const current=++generation;loading.value=true;error.value='';try{const [users,availableClients]=await Promise.all([props.request<UserResponse>('/api/contexto/usuarios'),props.request<Client[]>('/api/contexto/clientes')]);if(!alive||current!==generation)return;members.value=normalize(users);clients.value=availableClients.filter(item=>item.ativo!==false);loaded.value=true;}catch(cause){if(alive&&current===generation)error.value=message(cause);}finally{if(alive&&current===generation)loading.value=false;}}
function open(){actionError.value='';formError.value='';notice.value='';editing.value=true;}
function close(){if(!saving.value)editing.value=false;}
function resetForm(){mode.value='vincular';name.value='';email.value='';password.value='';role.value='operador';clientId.value='';formError.value='';}
async function update(member:Member,active:boolean){if(saving.value)return;actionError.value='';saving.value=true;const current=++generation;try{const body=member.cliente_id?{ativo:active,cliente_id:member.cliente_id}:{ativo:active,papel:member.papel||'operador'};await props.request('/api/contexto/usuarios/'+member.id,'PUT',body);if(!alive||current!==generation)return;member.ativo=active;notice.value=active?'Vínculo reativado.':'Vínculo revogado.';}catch(cause){if(alive&&current===generation)actionError.value=message(cause);}finally{if(alive&&current===generation)saving.value=false;}}
async function saveRole(member:Member){if(!member.papel||saving.value)return;saving.value=true;actionError.value='';const current=++generation;try{await props.request('/api/contexto/usuarios/'+member.id,'PUT',{ativo:member.ativo,papel:member.papel});if(alive&&current===generation)notice.value='Papel atualizado.';}catch(cause){if(alive&&current===generation)actionError.value=message(cause);}finally{if(alive&&current===generation)saving.value=false;}}
async function save(){if(saving.value)return;formError.value='';const normalizedEmail=email.value.trim().toLowerCase();const normalizedName=name.value.trim();if(!normalizedEmail||!normalizedEmail.includes('@')){formError.value='Informe um e-mail v�lido.';return;}if(mode.value==='cadastrar'&&(normalizedName.length<2||password.value.length<15)){formError.value='Informe nome e senha inicial v�lidos.';return;}if(role.value==='cliente'&&!clientId.value){formError.value='Selecione a empresa representada.';return;}if(role.value!=='cliente'&&clientId.value){formError.value='Empresa s� pode ser informada para representantes.';return;}saving.value=true;const operation=mode.value;try{const payload={modo:mode.value,email:normalizedEmail,papel:role.value,...(role.value==='cliente'?{cliente_id:Number(clientId.value)}:{}),...(mode.value==='cadastrar'?{nome:normalizedName,senha:password.value}:{})};await props.request('/api/contexto/usuarios','POST',payload);if(!alive)return;resetForm();notice.value=operation==='cadastrar'?'Conta cadastrada e vinculada.':'Conta vinculada ao escrit�rio.';saving.value=false;await load();}catch(cause){if(alive)formError.value=message(cause);}finally{if(alive)saving.value=false;}}
onMounted(()=>{void load();});
onBeforeUnmount(()=>{alive=false;generation++;});
</script>

<template>
  <section class="team-panel" aria-label="Equipe e acessos">
    <header class="team-heading"><div><span class="eyebrow">Acesso contextual</span><h2>Equipe e acessos</h2><p>Gerencie os vínculos deste escritório sem alterar a conta pessoal de cada usuário.</p></div><button type="button" class="primary" :disabled="loading" @click="open">Gerenciar equipe e acessos</button></header>
    <p v-if="loading" role="status">Consultando equipe e acessos…</p>
    <div v-if="error" class="team-error" role="alert"><p>{{ error }}</p><button type="button" class="secondary" :disabled="loading" @click="load">Tentar novamente</button></div>
    <article v-if="loaded&&!error" class="team-summary"><strong>{{ activeMembers }}</strong><span>vínculos ativos neste escritório</span><span>{{ members.length }} no total, incluindo revogados</span></article>
    <AppDialog v-if="editing" title="Equipe e acessos" :busy="saving" @close="close">
      <p>A conta é pessoal. Revogar remove somente o vínculo com este escritório. Vincular uma conta existente preserva sua senha.</p>
      <p v-if="notice" role="status">{{ notice }}</p><p v-if="actionError" role="alert">{{ actionError }}</p>
      <div v-if="loaded&&!error" class="team-scroll"><table aria-label="Equipe e representantes"><caption>Membros e representantes vinculados</caption><thead><tr><th scope="col">Pessoa</th><th scope="col">Papel</th><th scope="col">Situação</th><th scope="col">Ações</th></tr></thead><tbody><tr v-for="member in members" :key="member.id"><td><strong>{{ member.nome }}</strong><small>{{ member.email }}</small></td><td><template v-if="member.cliente_id"><span>Representante · empresa #{{ member.cliente_id }}</span></template><select v-else :aria-label="'Papel de '+member.nome" v-model="member.papel" :disabled="saving"><option value="operador">Operador</option><option value="administrador">Administrador</option></select></td><td><span class="status-badge" :data-tone="member.ativo?'success':'danger'">{{ member.ativo?'Ativo':'Vínculo revogado' }}</span></td><td class="team-actions"><button v-if="!member.cliente_id" type="button" class="secondary" :disabled="saving" :aria-label="'Salvar papel de '+member.nome" @click="saveRole(member)">Salvar papel</button><button type="button" class="secondary" :disabled="saving" :aria-label="(member.ativo?'Revogar vínculo de ':'Reativar vínculo de ')+member.nome" @click="update(member,!member.ativo)">{{ member.ativo?'Revogar vínculo':'Reativar vínculo' }}</button></td></tr><tr v-if="!members.length"><td colspan="4">Ainda não há vínculos neste escritório.</td></tr></tbody></table></div>
      <form class="vue-form team-form" @submit.prevent="save"><h3>Operação de usuário</h3><label>Operação de usuário<select v-model="mode" :disabled="saving"><option value="vincular">Vincular conta existente</option><option value="cadastrar">Cadastrar nova conta</option></select></label><label>E-mail da conta<input v-model="email" type="email" autocomplete="email" maxlength="254" required :disabled="saving"></label><label>Nome da nova conta<input v-model="name" type="text" autocomplete="name" minlength="2" maxlength="250" :disabled="saving||mode==='vincular'" :required="mode==='cadastrar'"></label><label>Senha inicial da nova conta<input v-model="password" type="password" autocomplete="new-password" minlength="15" maxlength="128" :disabled="saving||mode==='vincular'" :required="mode==='cadastrar'"></label><label>Papel da conta<select v-model="role" :disabled="saving"><option value="operador">Operador</option><option value="administrador">Administrador</option><option value="cliente">Representante da empresa</option></select></label><label v-if="role==='cliente'">Empresa representada<select v-model="clientId" :disabled="saving" required><option value="">Selecione uma empresa</option><option v-for="client in clients" :key="client.id" :value="String(client.id)">{{ client.razao_social }}</option></select></label><p v-if="formError" role="alert">{{ formError }}</p><footer><button type="button" class="secondary" :disabled="saving" @click="resetForm">Limpar formulário</button><button type="submit" class="primary" :disabled="saving">{{ saving?'Salvando…':'Salvar vínculo/conta' }}</button></footer></form>
    </AppDialog>
  </section>
</template>

<style scoped>
.team-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-top:32px}.team-heading h2{margin:4px 0 8px}.team-heading p{margin:0;color:var(--muted)}.team-summary{display:flex;align-items:baseline;gap:12px;flex-wrap:wrap;max-width:1000px;margin-top:18px;padding:18px 22px;border:1px solid var(--line);border-radius:var(--radius-card);background:var(--surface)}.team-summary strong{font-size:28px;font-variant-numeric:tabular-nums}.team-summary span{color:var(--muted)}.team-error{margin-top:20px;padding:14px;border-radius:var(--radius-control);background:color-mix(in srgb,var(--danger) 12%,transparent)}.team-error p{margin:0 0 10px}.team-scroll{overflow-x:auto}.team-scroll table{width:100%;min-width:760px;border-collapse:collapse}.team-scroll th,.team-scroll td{padding:14px 12px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}.team-scroll th{color:var(--muted);font-size:.8rem}.team-scroll td strong,.team-scroll td small{display:block}.team-scroll td small{margin-top:4px;color:var(--muted);overflow-wrap:anywhere}.team-scroll select{min-width:150px;padding:9px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--bg);color:var(--ink);font:inherit}.team-actions{white-space:nowrap}.team-actions button+button{margin-left:8px}.team-form{margin-top:22px;padding-top:22px;border-top:1px solid var(--line)}.team-form h3{margin:0}.team-form footer{display:flex;justify-content:flex-end;gap:12px}@media(max-width:700px){.team-heading button{width:100%}.team-summary{align-items:flex-start;flex-direction:column}.team-form footer{flex-direction:column}.team-form footer button{width:100%}}
</style>
